    :root {
      color-scheme: dark;
    }
    body {
      background-color: #121212;
      color: #e0e0e0;
      font-family: system-ui, -apple-system, sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      margin: 0;
    }
    .preview-container {
      background-color: #1e1e1e;
      border: 1px solid #333;
      border-radius: 8px;
      padding: 16px;
      text-align: center;
      max-width: 400px;
      width: 100%;
      box-shadow: 0 4px 6px rgba(0,0,0,0.3);
      box-sizing: border-box;
    }
    .preview-image {
      max-width: 100%;
      height: auto;
      border-radius: 4px;
      margin-bottom: 16px;
      display: block;
    }

    /* Trigger Button */
    button.trigger {
      background-color: #cf6679;
      color: #000;
      border: none;
      padding: 8px 16px;
      border-radius: 4px;
      font-weight: 600;
      font-size: 1rem;
      cursor: pointer;
      transition: background-color 0.2s ease;
    }
    button.trigger:hover {
      background-color: #ff7597;
    }
    button.trigger:focus-visible {
      outline: 2px solid #fff;
      outline-offset: 2px;
    }

    /* Native Dialog */
    dialog {
      background-color: #2c2c2c;
      color: #e0e0e0;
      border: 1px solid #444;
      border-radius: 8px;
      padding: 24px;
      box-shadow: 0 10px 25px rgba(0,0,0,0.5);
      max-width: 400px;
      width: 90%;
    }
    dialog::backdrop {
      background-color: rgba(0, 0, 0, 0.75);
    }
    dialog h2 {
      margin-top: 0;
      color: #fff;
      font-size: 1.25rem;
    }
    dialog p {
      line-height: 1.5;
      margin-bottom: 0;
    }
    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      margin-top: 24px;
    }

    /* Action Buttons */
    .btn {
      background-color: #444;
      color: #fff;
      border: 1px solid #555;
      padding: 8px 16px;
      border-radius: 4px;
      font-weight: 500;
      font-size: 1rem;
      cursor: pointer;
      transition: background-color 0.2s ease;
    }
    .btn:hover {
      background-color: #555;
    }
    .btn:focus-visible {
      outline: 2px solid #fff;
      outline-offset: 2px;
    }

    .btn-danger {
      background-color: #cf6679;
      color: #000;
      border: none;
    }
    .btn-danger:hover {
      background-color: #ff7597;
    }
    .btn-danger:focus-visible {
      outline: 2px solid #cf6679;
      outline-offset: 2px;
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <script type="text/babel">
    const { useState, useRef, useEffect } = React;

    function DeleteConfirmationDialog({ isOpen, onClose, onConfirm }) {
      const dialogRef = useRef(null);

      // Handle showing/closing the native dialog based on `isOpen` state
      useEffect(() => {
        const dialogNode = dialogRef.current;
        if (!dialogNode) return;

        if (isOpen && !dialogNode.open) {
          dialogNode.showModal();
        } else if (!isOpen && dialogNode.open) {
          dialogNode.close();
        }
      }, [isOpen]);

      // Handle Escape key behavior correctly with React state
      useEffect(() => {
        const dialogNode = dialogRef.current;

        const handleCancel = (event) => {
          event.preventDefault(); // Prevent native close
          onClose(); // Use state to close
        };

        if (dialogNode) {
          dialogNode.addEventListener('cancel', handleCancel);
          return () => dialogNode.removeEventListener('cancel', handleCancel);
        }
      }, [onClose]);

      return (
        <dialog 
          ref={dialogRef} 
          aria-labelledby="confirm-heading"
        >
          <h2 id="confirm-heading">Delete Image</h2>
          <p>Are you sure you want to delete this image from your library? This action cannot be undone.</p>
          <div className="dialog-actions">
            <button type="button" className="btn" onClick={onClose} autoFocus>
              Cancel
            </button>
            <button type="button" className="btn btn-danger" onClick={onConfirm}>
              Delete
            </button>
          </div>
        </dialog>
      );
    }

    function ImagePreview() {
      const [isDialogOpen, setIsDialogOpen] = useState(false);

      const openDialog = () => setIsDialogOpen(true);
      const closeDialog = () => setIsDialogOpen(false);

      const confirmDelete = () => {
        console.log("Image deleted.");
        closeDialog();
        // Here you would typically also remove the image or navigate away
      };

      return (
        <main className="preview-container">
          <img 
            src="https://images.unsplash.com/photo-1551214012-84f95e060dee?ixlib=rb-4.0.3&auto=format&fit=crop&w=400&q=80" 
            alt="Neon city skyline at night" 
            className="preview-image" 
          />
          <div>
            <button type="button" className="trigger" onClick={openDialog}>
              Delete Image
            </button>
          </div>

          <DeleteConfirmationDialog 
            isOpen={isDialogOpen} 
            onClose={closeDialog} 
            onConfirm={confirmDelete} 
          />
        </main>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<ImagePreview />);
  </script>
</body>
